    msg->sadb_msg_satype = 0;
    msg->sadb_msg_len = sizeof(*msg) / 4;
    msg->sadb_msg_reserved = 0;
    msg->sadb_msg_seq = c->seq;
    msg->sadb_msg_pid = c->portid;

