int flush_key_notification_policy(const struct km_event *c) {
    struct sk_buff *skb;
    struct pfkey_msg *hdr;
    int err = 0;

    skb = alloc_skb(PFKEY_SOCKET_BUFFER_SIZE, GFP_KERNEL);
    if (!skb) {
        return -ENOBUFS;
    }

    skb_put(skb, PFKEY_MSG_BASE_SIZE);
    hdr = skb->data;

    hdr->type = PFKEY_TYPE_FLUSH;
    hdr->satype = PFKEY_SATYPE_POLICY;
    hdr->reserved = 0;

    hdr->seq = c->seq;
    hdr->port_id = c->portid;

    err = pfkey_broadcast(skb, PFKEY_GROUPBYPOLICY, GFP_KERNEL);

    if (err < 0) {
        kfree_skb(skb);
        return err;
    }

    return 0;
}

